% 常用包
\usepackage{booktabs}
\usepackage{graphicx}
\usepackage{amsmath}
\usepackage{hyperref}
\usepackage{natbib}  % 或 \usepackage[numbers]{natbib}

% 标题
\title{Death Avoidance Dominates Routing Signal in LLM Agent Computation}

% 匿名投稿
\author{Anonymous}

\begin{document}
\maketitle

\input{abstract}
\input{introduction}
\input{method}
\input{experiments}
\input{related_work}
\input{conclusion}

\bibliographystyle{acl_natbib}
